  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchTrades (public)
    //
    //     {
    //         "id":"c152f814-8eeb-44f0-8f3f-e5c568f2ffcf",
    //         "isMakerBuyer":false,
    //         "baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f",
    //         "quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5",
    //         "price":"4435.56",
    //         "quantity":"0.32534",
    //         "cost":"1443.0650904",
    //         "timestamp":1635854642725,
    //         "makerBuyer":false
    //     }
    //
    // fetchMyTrades (private)
    //
    //     {
    //         "id":"02e02533-b4bf-4ba9-9271-24e2108dfbf7",
    //         "isMakerBuyer":false,
    //         "direction":"TRADE_DIRECTION_BUY",
    //         "baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f",
    //         "quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5",
    //         "price":"4564.32",
    //         "quantity":"0.01000",
    //         "cost":"45.6432",
    //         "fee":"0.223651680000000000",
    //         "order":"c9cac6a0-484c-4892-88e7-ad51b39f2ce1",
    //         "timestamp":1635921580399,
    //         "makerBuyer":false
    //     }
    //
    ccxt::any type = ccxt::any{};
    ccxt::any timestamp = this->safeInteger(trade, std::string("timestamp"));
    ccxt::any priceString = this->safeString(trade, std::string("price"));
    ccxt::any amountString = this->safeString(trade, std::string("quantity"));
    ccxt::any costString = this->safeString(trade, std::string("cost"));
    ccxt::any makerBuyer = this->safeValue(trade, std::string("makerBuyer"));
    ccxt::any side = this->safeString(trade, std::string("direction"));
    if (isTrue(isEqual(side, ccxt::any{}))) {
      side =
          (isTrue((isEqual(makerBuyer, true))) ? ccxt::any(std::string("sell"))
                                               : ccxt::any(std::string("buy")));
    } else {
      if (isTrue(isEqual(side, std::string("TRADE_DIRECTION_BUY")))) {
        side = std::string("buy");
      } else if (isTrue(isEqual(side, std::string("TRADE_DIRECTION_SELL")))) {
        side = std::string("sell");
      }
    }
    ccxt::any isBuy = (isEqual(side, std::string("buy")));
    ccxt::any isMaker = isTrue((isEqual(makerBuyer, true))) && isTrue(isBuy);
    ccxt::any takerOrMaker =
        (isTrue(isMaker) ? ccxt::any(std::string("maker"))
                         : ccxt::any(std::string("taker")));
    ccxt::any baseId = this->safeString(trade, std::string("baseCurrency"));
    ccxt::any quoteId = this->safeString(trade, std::string("quoteCurrency"));
    ccxt::any base = this->safeCurrencyCode(baseId);
    ccxt::any quote = this->safeCurrencyCode(quoteId);
    ccxt::any symbol = add(add(base, std::string("/")), quote);
    if (isTrue(isTrue((!isEqual(this->markets, ccxt::any{}))) &&
               isTrue((inOp(this->markets, symbol))))) {
      market = this->market(symbol);
    }
    ccxt::any id = this->safeString(trade, std::string("id"));
    ccxt::any orderId = this->safeString(trade, std::string("order"));
    ccxt::any feeCost = this->safeString(trade, std::string("fee"));
    ccxt::any fee = ccxt::any{};
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), quote},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("id"), id},
            {std::string("order"), orderId},
            {std::string("type"), type},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("side"), side},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), costString},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name latoken#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see https://api.latoken.com/doc/v2/#tag/Trade/operation/getTradesByPair
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(market, std::string("baseId"))},
                     {std::string("quote"),
                      ::getValue(market, std::string("quoteId"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 100)); // default 100, limit 100
                 }
                 ccxt::any response =
                     awaitValue(this->publicGetTradeHistoryCurrencyQuote(
                         this->extend(request, params)));
                 //
                 //     [
                 //         {"id":"c152f814-8eeb-44f0-8f3f-e5c568f2ffcf","isMakerBuyer":false,"baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f","quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5","price":"4435.56","quantity":"0.32534","cost":"1443.0650904","timestamp":1635854642725,"makerBuyer":false},
                 //         {"id":"cfecbefb-3d11-43d7-b9d4-fa16211aad8a","isMakerBuyer":false,"baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f","quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5","price":"4435.13","quantity":"0.26540","cost":"1177.083502","timestamp":1635854641114,"makerBuyer":false},
                 //         {"id":"f43d3ec8-db94-49f3-b534-91dbc2779296","isMakerBuyer":true,"baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f","quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5","price":"4435.00","quantity":"0.41738","cost":"1851.0803","timestamp":1635854640323,"makerBuyer":true},
                 //     ]
                 //
                 return this->parseTrades(response, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name latoken#fetchTradingFee
   * @description fetch the trading fees for a market
   * @see https://api.latoken.com/doc/v2/#tag/Trade/operation/getFeeByPair
   * @see https://api.latoken.com/doc/v2/#tag/Trade/operation/getAuthFeeByPair
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [fee structure]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<ccxt::any>
  fetchTradingFee(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any options = this->safeValue(
                     this->options, std::string("fetchTradingFee"),
                     ccxt::dict{});
                 ccxt::any defaultMethod =
                     this->safeString(options, std::string("method"),
                                      std::string("fetchPrivateTradingFee"));
                 ccxt::any method = this->safeString(
                     params, std::string("method"), defaultMethod);
                 params = this->omit(params, std::string("method"));
                 if (isTrue(isEqual(method,
                                    std::string("fetchPrivateTradingFee")))) {
                   return awaitValue(
                       this->fetchPrivateTradingFee(symbol, params));
                 } else if (isTrue(isEqual(
                                method,
                                std::string("fetchPublicTradingFee")))) {
                   return awaitValue(
                       this->fetchPublicTradingFee(symbol, params));
                 } else {
                   throw NotSupported(toString(
                       add(this->id, std::string(" not support this method"))));
                 }
                 return ccxt::any{};
               })
        .share();
  }

