  /**
   * @method
   * @name latoken#createOrder
   * @description create a trade order
   * @see https://api.latoken.com/doc/v2/#tag/Order/operation/placeOrder
   * @see https://api.latoken.com/doc/v2/#tag/StopOrder/operation/placeStopOrder
   * // stop
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.triggerPrice] the price at which a trigger order is
   * triggered at
   *
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {string} [params.condition] "GTC", "IOC", or  "FOK"
   * @param {string} [params.clientOrderId] [ 0 .. 50 ] characters, client's
   * custom order id (free field for your convenience)
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any uppercaseType = toUpperCase(type);
                 if (isTrue(isEqual(side, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " createOrder() requires a side argument"))));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("baseCurrency"),
                      ::getValue(market, std::string("baseId"))},
                     {std::string("quoteCurrency"),
                      ::getValue(market, std::string("quoteId"))},
                     {std::string("side"), toUpperCase(side)},
                     {std::string("condition"), std::string("GTC")},
                     {std::string("type"), uppercaseType},
                     {std::string("clientOrderId"), this->uuid()},
                     {std::string("quantity"),
                      this->amountToPrecision(symbol, amount)},
                     {std::string("timestamp"), this->seconds()},
                 };
                 if (isTrue(isEqual(uppercaseType, std::string("LIMIT")))) {
                   ::setValue(request, std::string("price"),
                              this->priceToPrecision(symbol, price));
                 }
                 ccxt::any triggerPrice =
                     this->safeString2(params, std::string("triggerPrice"),
                                       std::string("stopPrice"));
                 params =
                     this->omit(params, ccxt::list{std::string("triggerPrice"),
                                                   std::string("stopPrice")});
                 ccxt::any response = ccxt::any{};
                 if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                   ::setValue(request, std::string("stopPrice"),
                              this->priceToPrecision(symbol, triggerPrice));
                   response = awaitValue(this->privatePostAuthStopOrderPlace(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privatePostAuthOrderPlace(
                       this->extend(request, params)));
                 }
                 //
                 //    {
                 //        "baseCurrency":
                 //        "f7dac554-8139-4ff6-841f-0e586a5984a0",
                 //        "quoteCurrency":
                 //        "a5a7a7a9-e2a3-43f9-8754-29a02f6b709b", "side":
                 //        "BID", "clientOrderId":
                 //        "my-wonderful-order-number-71566", "price":
                 //        "10103.19", "stopPrice": "10103.19", "quantity":
                 //        "3.21", "timestamp": 1568185507
                 //    }
                 //
                 return this->parseOrder(response, market);
               })
        .share();
  }

