  /**
   * @method
   * @name latoken#transfer
   * @description transfer currency internally between wallets on the same
   * account
   * @see https://api.latoken.com/doc/v2/#tag/Transfer/operation/transferByEmail
   * @see https://api.latoken.com/doc/v2/#tag/Transfer/operation/transferById
   * @see https://api.latoken.com/doc/v2/#tag/Transfer/operation/transferByPhone
   * @param {string} code unified currency code
   * @param {float} amount amount to transfer
   * @param {string} fromAccount account to transfer from
   * @param {string} toAccount account to transfer to
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [transfer structure]{@link
   * https://docs.ccxt.com/?id=transfer-structure}
   */
  std::shared_future<ccxt::any>
  transfer(ccxt::any code, ccxt::any amount, ccxt::any fromAccount,
           ccxt::any toAccount, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any currency = this->currency(code);
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("recipient"), toAccount},
                     {std::string("value"),
                      this->currencyToPrecision(code, amount)},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isGreaterThanOrEqual(
                         getIndexOf(toAccount, std::string("@")), 0))) {
                   response = awaitValue(this->privatePostAuthTransferEmail(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(getStringLength(toAccount), 36))) {
                   response = awaitValue(this->privatePostAuthTransferId(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privatePostAuthTransferPhone(
                       this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "id": "e6fc4ace-7750-44e4-b7e9-6af038ac7107",
                 //         "status": "TRANSFER_STATUS_COMPLETED",
                 //         "type": "TRANSFER_TYPE_DEPOSIT_SPOT",
                 //         "fromAccount":
                 //         "3bf61015-bf32-47a6-b237-c9f70df772ad", "toAccount":
                 //         "355eb279-7c7e-4515-814a-575a49dc0325",
                 //         "transferringFunds": "500000.000000000000000000",
                 //         "usdValue": "0.000000000000000000",
                 //         "rejectReason": "",
                 //         "timestamp": 1576844438402,
                 //         "direction": "INTERNAL",
                 //         "method": "TRANSFER_METHOD_UNKNOWN",
                 //         "recipient": "",
                 //         "sender": "",
                 //         "currency": "40af7879-a8cc-4576-a42d-7d2749821b58",
                 //         "codeRequired": false,
                 //         "fromUser": "cd555555-666d-46fb-9ae6-487f66738073",
                 //         "toUser": "cd555555-666d-46fb-9ae6-487f66738073",
                 //         "fee": 0
                 //     }
                 //
                 return this->parseTransfer(response);
               })
        .share();
  }

  ccxt::any parseTransfer(ccxt::any transfer,
                          ccxt::any currency = ccxt::any{}) override {
    //
    //     {
    //         "id": "e6fc4ace-7750-44e4-b7e9-6af038ac7107",
    //         "status": "TRANSFER_STATUS_COMPLETED",
    //         "type": "TRANSFER_TYPE_DEPOSIT_SPOT",
    //         "fromAccount": "3bf61015-bf32-47a6-b237-c9f70df772ad",
    //         "toAccount": "355eb279-7c7e-4515-814a-575a49dc0325",
    //         "transferringFunds": "500000.000000000000000000",
    //         "usdValue": "0.000000000000000000",
    //         "rejectReason": "",
    //         "timestamp": 1576844438402,
    //         "direction": "INTERNAL",
    //         "method": "TRANSFER_METHOD_UNKNOWN",
    //         "recipient": "",
    //         "sender": "",
    //         "currency": "40af7879-a8cc-4576-a42d-7d2749821b58",
    //         "codeRequired": false,
    //         "fromUser": "cd555555-666d-46fb-9ae6-487f66738073",
    //         "toUser": "cd555555-666d-46fb-9ae6-487f66738073",
    //         "fee": 0
    //     }
    //
    ccxt::any timestamp =
        this->safeTimestamp(transfer, std::string("timestamp"));
    ccxt::any currencyId = this->safeString(transfer, std::string("currency"));
    ccxt::any status = this->safeString(transfer, std::string("status"));
    return ccxt::dict{
        {std::string("info"), transfer},
        {std::string("id"), this->safeString(transfer, std::string("id"))},
        {std::string("timestamp"),
         this->safeInteger(transfer, std::string("timestamp"))},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("currency"), this->safeCurrencyCode(currencyId, currency)},
        {std::string("amount"),
         this->safeNumber(transfer, std::string("transferringFunds"))},
        {std::string("fromAccount"),
         this->safeString(transfer, std::string("fromAccount"))},
        {std::string("toAccount"),
         this->safeString(transfer, std::string("toAccount"))},
        {std::string("status"), this->parseTransferStatus(status)},
    };
  }

  virtual ccxt::any parseTransferStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("TRANSFER_STATUS_COMPLETED"), std::string("ok")},
        {std::string("TRANSFER_STATUS_PENDING"), std::string("pending")},
        {std::string("TRANSFER_STATUS_REJECTED"), std::string("failed")},
        {std::string("TRANSFER_STATUS_UNVERIFIED"), std::string("pending")},
        {std::string("TRANSFER_STATUS_CANCELLED"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any request =
        add(add(add(std::string("/"), this->version), std::string("/")),
            this->implodeParams(path, params));
    ccxt::any requestString = request;
    ccxt::any query = this->omit(params, this->extractParams(path));
    ccxt::any urlencodedQuery = this->urlencode(query);
    if (isTrue(isEqual(method, std::string("GET")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        requestString =
            add(requestString, add(std::string("?"), urlencodedQuery));
      }
    }
    if (isTrue(isEqual(api, std::string("private")))) {
      this->checkRequiredCredentials();
      ccxt::any auth = add(add(method, request), urlencodedQuery);
      ccxt::any signature =
          this->hmac(this->encode(auth), this->encode(this->secret), sha512);
      headers = ccxt::dict{
          {std::string("X-LA-APIKEY"), this->apiKey},
          {std::string("X-LA-SIGNATURE"), signature},
          {std::string("X-LA-DIGEST"), std::string("HMAC-SHA512")},
      };
      if (isTrue(isEqual(method, std::string("POST")))) {
        ::setValue(headers, std::string("Content-Type"),
                   std::string("application/json"));
        body = this->json(query);
      }
    }
    ccxt::any url = add(::getValue(::getValue(this->urls, std::string("api")),
                                   std::string("rest")),
                        requestString);
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  ccxt::any handleErrors(ccxt::any code, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    if (isTrue(isEqual(response, ccxt::any{}))) {
      return ccxt::any{};
    }
    //
    // {"result":false,"message":"invalid API key, signature or
    // digest","error":"BAD_REQUEST","status":"FAILURE"}
    // {"result":false,"message":"request expired or bad <timeAlive>/<timestamp>
    // format","error":"BAD_REQUEST","status":"FAILURE"}
    // {"message":"Internal Server
    // Error","error":"INTERNAL_ERROR","status":"FAILURE"}
    // {"result":false,"message":"Internal error","error":"For input string:
    // \"NaN\"","status":"FAILURE"}
    //
    ccxt::any message = this->safeString(response, std::string("message"));
    ccxt::any feedback = add(add(this->id, std::string(" ")), body);
    if (isTrue(!isEqual(message, ccxt::any{}))) {
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), message,
          feedback);
      this->throwBroadlyMatchedException(
          ::getValue(this->exceptions, std::string("broad")), message,
          feedback);
    }
    ccxt::any error = this->safeValue(response, std::string("error"));
    ccxt::any errorMessage = this->safeString(error, std::string("message"));
    if (isTrue(isTrue((!isEqual(error, ccxt::any{}))) ||
               isTrue((!isEqual(errorMessage, ccxt::any{}))))) {
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), error, feedback);
      this->throwBroadlyMatchedException(
          ::getValue(this->exceptions, std::string("broad")), body, feedback);
      throw ExchangeError(toString(feedback));
    }
    return ccxt::any{};
  }
